#!/usr/bin/env bash
set -euo pipefail
WORKDIR="/home/kavia/workspace/code-generation/employee-management-portal-66484-66615/FrontendApplication"
cd "$WORKDIR"
# check package.json presence
if ! [[ -f package.json ]]; then echo "ERROR: package.json missing" >&2; exit 6; fi
# if react absent, run install to produce node_modules and package-lock.json
node -e "const p=require('./package.json'); process.exit((p.dependencies&&p.dependencies.react)|| (p.devDependencies&&p.devDependencies.react)?0:1)" 2>/dev/null || {
  npm install --no-audit --no-fund --silent react@^18.2.0 react-dom@^18.2.0 || { echo 'ERROR: npm install react failed' >&2; exit 7; }
}
# install devDependencies (pin key versions)
npm install --no-audit --no-fund --silent --save-dev webpack@^5 webpack-cli@^4 webpack-dev-server@^4 @babel/core@^7 babel-loader@^8 @babel/preset-env@^7 @babel/preset-react@^7 html-webpack-plugin@^5 jest@^29 babel-jest@^29 || { echo 'ERROR: npm install devDependencies failed' >&2; exit 8; }
# validate installation
if [[ ! -d node_modules/react ]]; then echo 'ERROR: react not found in node_modules' >&2; exit 9; fi
if [[ ! -x ./node_modules/.bin/webpack ]]; then echo 'ERROR: local webpack binary missing' >&2; exit 10; fi
mkdir -p logs
